const workspaceAlias = Object.fromEntries(
  readdirSync(workspaceSrc, { withFileTypes: true })
    .filter(
      (entry) =>
        entry.isDirectory() && existsSync(join(workspaceSrc, entry.name, "src", "index.ts")),
    )
    .map((entry) => [
      `@autolight/${entry.name}`,
      join(workspaceSrc, entry.name, "src", "index.ts"),
    ]),
);

resolve: {
  alias: [
    {
      find: /^@autolight\/([^/]+)\/([^/]+)$/,
      replacement: join(workspaceSrc, "$1", "src", "$2.ts"),
    },
    ...Object.entries(workspaceAlias).map(([find, replacement]) => ({ find, replacement })),
  ],
},
